/// <summary>The session a client is using: pyBYD's <c>Session</c> fields.</summary>
/// <remarks><c>ToString</c> leaves the secrets out.</remarks>
[JsonConverter(typeof(SessionInfoJson))]
public sealed record SessionInfo
{
    /// <summary>The account's user ID.</summary>
    [JsonPropertyName("user_id")]
    public required string UserId { get; init; }

    /// <summary>The token requests are signed with. A secret.</summary>
    [JsonPropertyName("sign_token")]
    public required string SignToken { get; init; }

    /// <summary>The token the content key derives from. A secret.</summary>
    [JsonPropertyName("encry_token")]
    public required string EncryToken { get; init; }

    /// <summary>When the session was made, in the client's monotonic seconds.</summary>
    [JsonPropertyName("created_at")]
    public required double CreatedAt { get; init; }

    /// <summary>Seconds the session lives; infinite for no expiry.</summary>
    [JsonPropertyName("ttl")]
    public required double Ttl { get; init; }

    private bool PrintMembers(StringBuilder builder)
    {
        builder.Append("UserId = ").Append((object?)UserId);
        builder.Append(", SignToken = ***");
        builder.Append(", EncryToken = ***");
        builder.Append(", CreatedAt = ").Append((object?)CreatedAt);
        builder.Append(", Ttl = ").Append((object?)Ttl);
        return true;
    }
}

/// <summary>
/// A session as an application stores it, to resume later without a password login. Give it back
/// unchanged to <c>ImportSessionAsync</c>.
/// </summary>
/// <remarks><c>ToString</c> leaves the secrets out.</remarks>
[JsonConverter(typeof(SessionTokensJson))]
public sealed record SessionTokens
{
    /// <summary>The account's user ID.</summary>
    [JsonPropertyName("user_id")]
    public required string UserId { get; init; }

    /// <summary>The token requests are signed with. A secret.</summary>
    [JsonPropertyName("sign_token")]
    public required string SignToken { get; init; }

    /// <summary>The token the content key derives from. A secret.</summary>
    [JsonPropertyName("encry_token")]
    public required string EncryToken { get; init; }

    /// <summary>Seconds the session has left; null for no expiry.</summary>
    [JsonPropertyName("ttl_remaining")]
    public required double? TtlRemaining { get; init; }

    /// <summary>Whether the account reaches each VIN as a guest.</summary>
    [JsonPropertyName("guest_vins")]
    public required IReadOnlyDictionary<string, bool> GuestVins { get; init; }

    private bool PrintMembers(StringBuilder builder)
    {
        builder.Append("UserId = ").Append((object?)UserId);
        builder.Append(", SignToken = ***");
        builder.Append(", EncryToken = ***");
        builder.Append(", TtlRemaining = ").Append((object?)TtlRemaining);
        builder.Append(", GuestVins = ").Append((object?)GuestVins);
        return true;
    }
}

/// <summary>One request the client sent, for metrics.</summary>
[JsonConverter(typeof(RequestRecordJson))]
public sealed record RequestRecord
{
    /// <summary>The endpoint, such as <c>/control/getGpsInfo</c>.</summary>
    [JsonPropertyName("endpoint")]
    public required string Endpoint { get; init; }

    /// <summary>
    /// <c>reply</c> (the API answered), <c>transport</c> (the HTTP request failed) or <c>failed</c>.
    /// </summary>
    [JsonPropertyName("outcome")]
    public required string Outcome { get; init; }

    /// <summary>The reply's code; <c>0</c> is success. Null unless the API answered.</summary>
    [JsonPropertyName("code")]
    public required string? Code { get; init; }

    /// <summary>The HTTP status of a transport failure, when the server answered.</summary>
    [JsonPropertyName("status")]
    public required long? Status { get; init; }

    /// <summary>The error class of any other failure.</summary>
    [JsonPropertyName("error")]
    public required string? Error { get; init; }

    /// <summary>How long the request took, in seconds.</summary>
    [JsonPropertyName("duration")]
    public required double Duration { get; init; }
}

